import React from 'react';

const About = () => {
  const skills = [
    {
      category: 'Design',
      items: ['Brand Identity', 'Logo Design', 'Print Design', 'Packaging', 'Editorial'],
    },
    {
      category: 'Digital',
      items: ['UI/UX Design', 'Web Design', 'Motion Graphics', 'Social Media', 'Digital Marketing'],
    },
    {
      category: 'Tools',
      items: ['Adobe Creative Suite', 'Figma', 'Sketch', 'InDesign', 'Illustrator'],
    },
  ];

  const experience = [
    {
      year: '2021 - Present',
      title: 'Senior Graphic Designer',
      company: 'Creative Studio Inc.',
      description: 'Leading design projects for global brands and managing junior designers.',
    },
    {
      year: '2018 - 2021',
      title: 'Graphic Designer',
      company: 'Design Agency Co.',
      description: 'Created visual identities and marketing materials for diverse clients.',
    },
    {
      year: '2016 - 2018',
      title: 'Junior Designer',
      company: 'Brand Works',
      description: 'Started my professional journey working on brand and print projects.',
    },
  ];

  return (
    <div className="section" style={{ paddingTop: '120px' }}>
      <div className="container">
        <div className="about-grid">
          {/* Profile Image */}
          <div className="about-image">
            <div className="about-image-frame">
              <div className="about-image-inner">
                Photo
              </div>
            </div>
          </div>

          {/* About Content */}
          <div className="about-content">
            <p className="section-label">About Me</p>
            <h2>Creative Designer with a Passion for Timeless Design</h2>

            <p>
              Hello! I\'m a graphic designer with over 7 years of experience creating
              visual identities and brand experiences. My approach combines classic
              design principles with contemporary aesthetics, resulting in work that
              feels both timeless and fresh.
            </p>

            <p>
              I believe that great design should tell a story. Every project I take on
              is an opportunity to craft a visual narrative that connects brands with
              their audiences in meaningful ways. Whether it\'s a complete brand
              identity, a carefully crafted print piece, or a digital experience, I
              bring the same attention to detail and commitment to excellence.
            </p>

            <p>
              When I\'m not designing, you\'ll find me exploring vintage bookstores,
              visiting art exhibitions, or hunting for inspiration in the everyday
              details of city life.
            </p>
          </div>
        </div>

        {/* Skills Section */}
        <div className="skills-section">
          <p className="section-label">Expertise</p>
          <h2>Skills &amp; Capabilities</h2>

          <div className="skills-grid">
            {skills.map((skillGroup, index) => (
              <div key={index} className="skill-category">
                <h4 className="skill-category-title">{skillGroup.category}</h4>
                <ul className="skill-list">
                  {skillGroup.items.map((skill, skillIndex) => (
                    <li key={skillIndex} className="skill-item">
                      {skill}
                    </li>
                  ))}
                </ul>
              </div>
            ))}
          </div>
        </div>

        {/* Experience Section */}
        <div className="skills-section">
          <p className="section-label">Experience</p>
          <h2>Work History</h2>

          <div className="grid" style={{ marginTop: 'var(--space-10)' }}>
            {experience.map((job, index) => (
              <div
                key={index}
                style={{
                  borderTop: '1px solid var(--color-border)',
                  paddingTop: 'var(--space-6)',
                }}
              >
                <div className="flex justify-between items-start mb-4">
                  <div>
                    <h3 style={{ fontSize: 'var(--text-xl)', marginBottom: 'var(--space-1)' }}>
                      {job.title}
                    </h3>
                    <p style={{ color: 'var(--color-gray)' }}>{job.company}</p>
                  </div>
                  <span
                    className="text-mono"
                    style={{ color: 'var(--color-accent)', whiteSpace: 'nowrap' }}
                  >
                    {job.year}
                  </span>
                </div>
                <p style={{ color: 'var(--color-gray-dark)' }}>{job.description}</p>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default About;
